#include <iostream>
#include <stack>
#include <string>
using namespace std;

// 判断是否为运算符
bool isOperator(char c) {
    return c=='+' || c=='-' || c=='*' || c=='/';
}

// 比较优先级：返回正数表示a优先级高
int precedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;  // 括号
}

// 中缀表达式转后缀表达式
string infixToPostfix(string infix) {
    stack<char> opStack;
    string postfix;
    for (char c : infix) {
        if (isdigit(c)) {
            postfix += c;
        } else if (c == '(') {
            opStack.push(c);
        } else if (c == ')') {
            while (opStack.top() != '(') {
                postfix += opStack.top();
                opStack.pop();
            }
            opStack.pop();  // 弹出'('
        } else if (isOperator(c)) {
            while (!opStack.empty() && precedence(opStack.top()) >= precedence(c)) {
                postfix += opStack.top();
                opStack.pop();
            }
            opStack.push(c);
        }
    }
    while (!opStack.empty()) {
        postfix += opStack.top();
        opStack.pop();
    }
    return postfix;
}

// 计算后缀表达式
int evaluatePostfix(string postfix) {
    stack<int> numStack;
    for (char c : postfix) {
        if (isdigit(c)) {
            numStack.push(c - '0');
        } else {
            int b = numStack.top(); numStack.pop();
            int a = numStack.top(); numStack.pop();
            switch(c) {
                case '+': numStack.push(a + b); break;
                case '-': numStack.push(a - b); break;
                case '*': numStack.push(a * b); break;
                case '/': numStack.push(a / b); break;
            }
        }
    }
    return numStack.top();
}

