#include <stack>
#include <queue>
using namespace std;

// 方法1：两个栈实现队列
// 思路：栈1用于入队，栈2用于出队
class MyQueue {
private:
    stack<int> s1, s2;
public:
    void push(int x) { s1.push(x); }  // O(1)

    int pop() {  // 均摊O(1)
        if (s2.empty()) {
            while (!s1.empty()) { s2.push(s1.top()); s1.pop(); }
        }
        int val = s2.top(); s2.pop();
        return val;
    }

    int peek() {
        if (s2.empty()) {
            while (!s1.empty()) { s2.push(s1.top()); s1.pop(); }
        }
        return s2.top();
    }

    bool empty() { return s1.empty() && s2.empty(); }
};

// 方法2：两个队列实现栈
class MyStack {
private:
    queue<int> q1, q2;
public:
    void push(int x) {  // O(n) - 将新元素放到q1，把q1全部元素移到q2，再移回
        q2.push(x);
        while (!q1.empty()) { q2.push(q1.front()); q1.pop(); }
        swap(q1, q2);
    }

    int pop() {  // O(1)
        int val = q1.front(); q1.pop();
        return val;
    }

    int top() { return q1.front(); }
    bool empty() { return q1.empty(); }
};

// 另一种实现：用一个队列实现栈
class MyStack2 {
private:
    queue<int> q;
public:
    void push(int x) {
        q.push(x);
        // 将新元素前面的所有元素重新入队
        for (int i = 0; i < (int)q.size()-1; i++) {
            q.push(q.front()); q.pop();
        }
    }
    int pop() { int v = q.front(); q.pop(); return v; }
    int top() { return q.front(); }
    bool empty() { return q.empty(); }
};

